#include <assert.h>
#include "NoteFx/note_fx_arp.h"
static void expect(note_fx_arp_t*a,note_fx_arp_style_t s,uint8_t r,uint8_t w){uint8_t n=255,v=0;assert(note_fx_arp_next(a,s,r,&n,&v));assert(n==w&&v);}
int main(void){note_fx_arp_t a,b;note_fx_arp_init(&a,123);assert(note_fx_arp_note_on(&a,64,100));assert(note_fx_arp_note_on(&a,60,90));assert(note_fx_arp_note_on(&a,67,80));assert(note_fx_arp_note_on(&a,60,70));expect(&a,NOTE_FX_ARP_ORDER,1,64);expect(&a,NOTE_FX_ARP_ORDER,1,60);expect(&a,NOTE_FX_ARP_ORDER,1,67);a.phase=0;expect(&a,NOTE_FX_ARP_UP,2,60);expect(&a,NOTE_FX_ARP_UP,2,64);expect(&a,NOTE_FX_ARP_UP,2,67);expect(&a,NOTE_FX_ARP_UP,2,72);a.phase=0;expect(&a,NOTE_FX_ARP_DOWN,1,67);expect(&a,NOTE_FX_ARP_DOWN,1,64);a.phase=0;expect(&a,NOTE_FX_ARP_UP_DOWN,1,60);expect(&a,NOTE_FX_ARP_UP_DOWN,1,64);expect(&a,NOTE_FX_ARP_UP_DOWN,1,67);expect(&a,NOTE_FX_ARP_UP_DOWN,1,64);note_fx_arp_init(&a,77);note_fx_arp_init(&b,77);for(uint8_t n=0;n<4;n++){assert(note_fx_arp_note_on(&a,60+n,100));assert(note_fx_arp_note_on(&b,60+n,100));}for(uint8_t i=0;i<32;i++){uint8_t an,av,bn,bv;assert(note_fx_arp_next(&a,NOTE_FX_ARP_RANDOM,4,&an,&av));assert(note_fx_arp_next(&b,NOTE_FX_ARP_RANDOM,4,&bn,&bv));assert(an==bn&&an<=127);}uint32_t p=a.phase;assert(note_fx_arp_note_on(&a,80,100));assert(a.phase==p);assert(note_fx_arp_note_off(&a,61));assert(a.phase==p);note_fx_arp_init(&a,1);assert(note_fx_arp_note_on(&a,127,1));for(uint8_t i=0;i<8;i++)expect(&a,NOTE_FX_ARP_UP,4,127);note_fx_arp_init(&a,1);for(uint8_t i=0;i<NOTE_FX_ARP_MAX_SOURCES;i++)assert(note_fx_arp_note_on(&a,i,1));assert(!note_fx_arp_note_on(&a,100,1));return 0;}
